function keySwitches(s: string): number {
  let switches = 0;
  for (let i = 1; i < s.length; i++) {
    if ((s.charCodeAt(i) & ~32) !== (s.charCodeAt(i - 1) & ~32)) switches++;
  }
  return switches;
}

